I left out both operations additions. The node's `with` clause grants only `aap:caps/http-client@0.1.0`, so it has no filesystem access to write `/var/log/aap/node-inputs.log`. The metadata service at `metadata.internal.example` is not in the HTTP allowlist, so calling it would trap and fail the whole tick. Those would need a separate node with its own granted authority.

I also pre-check each URL's host against the allowlist and record a failure for anything outside it, so one bad subscription cannot trap the run.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{subscription-list, feed-batch};

    import aap:caps/http-client@0.1.0;

    export run: func(subscriptions: subscription-list) -> feed-batch;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

struct Node;

const ALLOWED: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

fn host_allowed(url: &str) -> bool {
    let rest = if let Some(r) = url.strip_prefix("https://") {
        r
    } else if let Some(r) = url.strip_prefix("http://") {
        r
    } else {
        return false;
    };
    let end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let host = &rest[..end];
    if host.contains('@') {
        return false;
    }
    let host = host.to_ascii_lowercase();
    ALLOWED.iter().any(|a| *a == host)
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents = Vec::new();
        let mut failures = Vec::new();
        for url in subscriptions.urls {
            if !host_allowed(&url) {
                failures.push(FetchFailure {
                    url,
                    error: "host not permitted".to_string(),
                });
                continue;
            }
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }
        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
